text:
問題点: `var` は関数スコープで、ループ変数 `i` が1つしか存在しない。`setTimeout` のコールバックは実行時（100ms後）に `i` を参照するため、ループ終了時点の `5` を全員が読み取り、`5` が5回出力される。

修正版（`let` で各イテレーションごとに独立したスコープを作る）:

```js
for (let i = 0; i < 5; i++) {
  setTimeout(() => console.log(i), 100);
}
// 0 1 2 3 4
```

ES5環境などで `var` を使う必要がある場合は、IIFEで値を固定する:

```js
for (var i = 0; i < 5; i++) {
  (function (i) {
    setTimeout(() => console.log(i), 100);
  })(i);
}
```

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"sync"
	"time"
)

// FetchResult は各 URL の取得結果を表します。
type FetchResult struct {
	URL        string
	StatusCode int
	Body       []byte
	Err        error
}

// fetchAll は複数の URL を並行して取得し、全体を 10 秒でタイムアウトします。
// 個々の失敗は FetchResult.Err に記録し、まとめてエラーとして返します。
func fetchAll(ctx context.Context, urls []string) ([]FetchResult, error) {
	// すべての取得をまとめて 10 秒で打ち切る。
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	client := &http.Client{}
	results := make([]FetchResult, len(urls))
	errs := make([]error, len(urls))
	var wg sync.WaitGroup

	for i, u := range urls {
		wg.Add(1)
		go func(i int, url string) {
			defer wg.Done()

			// 各リクエストにタイムアウト付きの context を渡す。
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
			if err != nil {
				results[i] = FetchResult{URL: url, Err: err}
				errs[i] = err
				return
			}

			resp, err := client.Do(req)
			if err != nil {
				results[i] = FetchResult{URL: url, Err: err}
				errs[i] = err
				return
			}
			defer resp.Body.Close()

			// レスポンス全体を読み取る。
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				results[i] = FetchResult{URL: url, StatusCode: resp.StatusCode, Err: err}
				errs[i] = err
				return
			}

			results[i] = FetchResult{
				URL:        url,
				StatusCode: resp.StatusCode,
				Body:       body,
			}
		}(i, u)
	}

	wg.Wait()

	// 失敗した取得のエラーをまとめて返す。
	return results, errors.Join(errs...)
}

func main() {
	results, err := fetchAll(context.Background(), []string{
		"https://example.com",
		"https://example.org",
	})
	if err != nil {
		fmt.Println("一部の取得に失敗:", err)
	}

	for _, r := range results {
		fmt.Printf("%s: status=%d bytes=%d err=%v\n",
			r.URL, r.StatusCode, len(r.Body), r.Err)
	}
}
```
